import React, { useState, useEffect } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import "./View.css";

const AdminViewTeachers = () => {
  const [teachers, setTeachers] = useState([]);

  const TeachersCollectionRef = collection(db, "teachers");

  // Fetch students from Firestore and sort alphabetically by name
  const fetchTeachers = async () => {
    const data = await getDocs(TeachersCollectionRef);
    const teachersData = data.docs.map((doc) => ({ ...doc.data(), id: doc.id }));

    // Sort students alphabetically by name
    teachersData.sort((a, b) => a.name.localeCompare(b.name));

    setTeachers(teachersData);
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  return (
    <div className="manage-students-container">
      <h2>View Registered Teachers</h2>
      <table className="students-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Class</th>
          </tr>
        </thead>
        <tbody>
          {teachers.length === 0 ? (
            <tr>
              <td colSpan="3">No teachers registered yet.</td>
            </tr>
          ) : (
            teachers.map((teacher) => (
              <tr key={teacher.id}>
                <td>{teacher.name}</td>
                <td>{teacher.email}</td>
                <td>{teacher.subject}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default AdminViewTeachers;
